[ApiController, Route("api/pedidos")]
public class PedidosController : ControllerBase {
  private readonly PedidoService _servicio;
  public PedidosController(PedidoService s) => _servicio = s;

  [HttpPost]
  public async Task<IActionResult> Crear(CrearPedidoDto dto) {
    var pedido = await _servicio.Crear(dto);   // negocio
    return Created($"/api/pedidos/{pedido.Id}", pedido);
  }
}

public class PedidoService {
  private readonly IPedidoRepositorio _repo;
  public async Task<Pedido> Crear(CrearPedidoDto dto) {
    if (dto.Cantidad <= 0) throw new ReglaException("Cantidad inválida");
    return await _repo.Guardar(new Pedido(dto.ProductoId, dto.Cantidad));
  }
}

