var builder = WebApplication.CreateBuilder(args);

builder.Services.AddDbContext<QatuDbContext>();          // Scoped
builder.Services.AddScoped<IProductoRepositorio, ProductoRepositorioEf>();
builder.Services.AddScoped<ProductoService>();
builder.Services.AddSingleton<IReloj, RelojSistema>();
builder.Services.AddTransient<IGeneradorCodigo, GeneradorCodigo>();

public class ProductoService {
  private readonly IProductoRepositorio _repo;
  public ProductoService(IProductoRepositorio repo) => _repo = repo;
}

[Fact]
public async Task ObtenerPrecio_DevuelvePrecioDelProducto() {
  var repo = new ProductoRepositorioEnMemoria();
  await repo.Guardar(new Producto(42, "Poncho", 25m));
  var servicio = new ProductoService(repo);

  var precio = await servicio.ObtenerPrecio(42);

  Assert.Equal(25m, precio);
}

